SELECT cstmr_name ,cstmr_cd ,email ,get_email_yn ,cellphone ,get_sms_yn FROM cstmr WHERE ((email !="" and get_email_yn = 'Y') or (LENGTH(replace(cellphone,"-","")) > 9 and get_sms_yn = 'Y'))
and substr(birth_day,6) = #{birthDay} AND (birth_day_ty_cd = #{birthDayTyCd}
or birth_day_ty_cd is null
)
